+pub fn weld_at_f32(facets: &[Triangle]) -> Result<Option<RepairReport>, GeoError> {
+    let q = |p: Point3| Point3::new(f64::from(p.x as f32), f64::from(p.y as f32), f64::from(p.z as f32));
+    let collapses = facets.iter().any(|t| {
